public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 3; i++) {
            int doubled = i * 2;
            System.out.println(i + " doubled is " + doubled);
        }
        // i and doubled are gone here.

        int biggest = 0;            // declared outside, so it survives
        for (int i = 1; i <= 5; i++) {
            if (i > biggest) {
                biggest = i;
            }
        }
        System.out.println("Biggest was " + biggest);
    }
}

