public class Main {
    static final int PASS_MARK = 40;
    static final String COURSE = "Java";

    public static void main(String[] args) {
        System.out.println(COURSE + " pass mark is " + PASS_MARK);
        report(92);
        report(31);
    }

    static void report(int marks) {
        if (marks >= PASS_MARK) {
            System.out.println(marks + ": pass");
        } else {
            System.out.println(marks + ": below " + PASS_MARK);
        }
    }
}

import java.util.Scanner;

public class Main {
    static final int PASS_MARK = 40;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("How many scores? ");
        int count = scanner.nextInt();

        int total = 0;
        for (int i = 1; i <= count; i++) {
            System.out.print("Score " + i + "? ");
            int score = scanner.nextInt();
            total += score;
            printBar(score);
            System.out.println(verdict(score));
        }

        System.out.println("Average: " + average(total, count));
    }

    static void printBar(int score) {
        System.out.print(score + " | ");
        for (int i = 1; i <= score / 10; i++) {
            System.out.print("*");
        }
        System.out.println();
    }

    static String verdict(int score) {
        return score >= PASS_MARK ? "pass" : "fail";
    }

    static double average(int total, int count) {
        if (count == 0) {
            return 0.0;
        }
        return (double) total / count;
    }
}

